:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa8;
  --track: #0f3460;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 3px solid var(--track);
  border-radius: 8px;
  padding: 24px;
  box-shadow: 0 0 0 4px rgba(233, 69, 96, 0.15);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 0.95rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

label {
  font-weight: 600;
  font-size: 0.95rem;
}

input {
  font: inherit;
  padding: 10px 12px;
  border-radius: 6px;
  border: 2px solid var(--track);
  background: var(--bg);
  color: var(--text);
}

input:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.error {
  color: var(--accent);
  font-weight: 600;
  margin: 0 0 12px;
}

.display {
  text-align: center;
  padding: 20px 0;
  margin: 8px 0 20px;
  border-top: 2px solid var(--track);
  border-bottom: 2px solid var(--track);
}

.phase {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
}

.time {
  margin: 4px 0;
  font-size: 3rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 2px;
}

.round {
  margin: 0 0 14px;
  color: var(--muted);
}

.progress-track {
  height: 12px;
  background: var(--track);
  border-radius: 6px;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  width: 0;
  background: var(--accent);
  transition: width 0.25s linear;
}

.controls {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

button {
  flex: 1 1 auto;
  min-width: 96px;
  font: inherit;
  font-weight: 700;
  padding: 12px 16px;
  border: 2px solid var(--accent);
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

button:hover:not(:disabled) { background: #c7304a; }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
button:active:not(:disabled) { transform: translateY(2px); }
button:disabled { opacity: 0.45; cursor: not-allowed; }

.complete {
  margin: 20px 0 0;
  text-align: center;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
}

@media (max-width: 400px) {
  .time { font-size: 2.4rem; }
  .card { padding: 18px; }
  button { min-width: 80px; }
}

const workInput = document.getElementById('workSeconds');
const restInput = document.getElementById('restSeconds');
const roundsInput = document.getElementById('totalRounds');
const phaseLabel = document.getElementById('phaseLabel');
const timeDisplay = document.getElementById('timeDisplay');
const roundLabel = document.getElementById('roundLabel');
const progressBar = document.getElementById('progressBar');
const startBtn = document.getElementById('startBtn');
const pauseBtn = document.getElementById('pauseBtn');
const resetBtn = document.getElementById('resetBtn');
const errorEl = document.getElementById('error');
const completeMsg = document.getElementById('completeMsg');

let timer = null;
let running = false;
let paused = false;
let phase = 'idle';
let round = 0;
let remaining = 0;
let phaseDuration = 0;
let workSeconds = 30;
let restSeconds = 15;
let totalRounds = 3;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function updateDisplay() {
  timeDisplay.textContent = formatTime(remaining);
  phaseLabel.textContent = phase === 'idle' ? 'Ready' : phase === 'work' ? 'Work' : phase === 'rest' ? 'Rest' : 'Done';
  roundLabel.textContent = 'Round ' + round + ' of ' + totalRounds;
  const pct = phaseDuration > 0 ? ((phaseDuration - remaining) / phaseDuration) * 100 : 0;
  progressBar.style.width = Math.min(100, Math.max(0, pct)) + '%';
}

function validate() {
  const w = parseInt(workInput.value, 10);
  const r = parseInt(restInput.value, 10);
  const n = parseInt(roundsInput.value, 10);
  if (!Number.isInteger(w) || w < 1 || w > 3600) return 'Work seconds must be 1-3600.';
  if (!Number.isInteger(r) || r < 1 || r > 3600) return 'Rest seconds must be 1-3600.';
  if (!Number.isInteger(n) || n < 1 || n > 99) return 'Rounds must be 1-99.';
  return null;
}

function startPhase(newPhase) {
  phase = newPhase;
  phaseDuration = newPhase === 'work' ? workSeconds : restSeconds;
  remaining = phaseDuration;
  updateDisplay();
}

function tick() {
  if (remaining > 0) {
    remaining--;
    updateDisplay();
    return;
  }
  if (phase === 'work') {
    startPhase('rest');
  } else if (phase === 'rest') {
    if (round >= totalRounds) {
      finish();
    } else {
      round++;
      startPhase('work');
    }
  }
}

function finish() {
  clearInterval(timer);
  timer = null;
  running = false;
  paused = false;
  phase = 'done';
  remaining = 0;
  progressBar.style.width = '100%';
  phaseLabel.textContent = 'Done';
  timeDisplay.textContent = '00:00';
  completeMsg.hidden = false;
  startBtn.disabled = false;
  pauseBtn.disabled = true;
  pauseBtn.textContent = 'Pause';
}

function start() {
  const err = validate();
  if (err) {
    errorEl.textContent = err;
    errorEl.hidden = false;
    return;
  }
  errorEl.hidden = true;
  completeMsg.hidden = true;
  workSeconds = parseInt(workInput.value, 10);
  restSeconds = parseInt(restInput.value, 10);
  totalRounds = parseInt(roundsInput.value, 10);
  round = 1;
  running = true;
  paused = false;
  startBtn.disabled = true;
  pauseBtn.disabled = false;
  startPhase('work');
  timer = setInterval(tick, 1000);
}

function togglePause() {
  if (!running) return;
  if (paused) {
    paused = false;
    pauseBtn.textContent = 'Pause';
    timer = setInterval(tick, 1000);
  } else {
    paused = true;
    pauseBtn.textContent = 'Resume';
    clearInterval(timer);
    timer = null;
  }
}

function reset() {
  clearInterval(timer);
  timer = null;
  running = false;
  paused = false;
  phase = 'idle';
  round = 0;
  remaining = 0;
  phaseDuration = 0;
  progressBar.style.width = '0%';
  phaseLabel.textContent = 'Ready';
  timeDisplay.textContent = '00:00';
  roundLabel.textContent = 'Round 0 of 0';
  completeMsg.hidden = true;
  errorEl.hidden = true;
  startBtn.disabled = false;
  pauseBtn.disabled = true;
  pauseBtn.textContent = 'Pause';
}

startBtn.addEventListener('click', start);
pauseBtn.addEventListener('click', togglePause);
resetBtn.addEventListener('click', reset);
reset();
